package com.example.websocket;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

/**
 * WebSocket upgrade filter that validates origin and handles
 * reverse proxy headers for proper client identification.
 * Deployed behind nginx with proxy_pass configuration.
 */
public class WebSocketUpgradeFilter implements Filter {

    private static final String WEBSOCKET_UPGRADE = "websocket";
    private static final String PROXY_SECRET_HEADER = "X-Proxy-Secret";
    private static final String TRUSTED_PROXY_SECRET = "k8s-internal-9f3a2b";
    private static final Set<String> ALLOWED_ORIGINS = new HashSet<>(Arrays.asList(
        "https://app.example.com",
        "https://www.example.com"
    ));

    private FilterConfig filterConfig;

    @Override
    public void init(FilterConfig config) throws ServletException {
        this.filterConfig = config;
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest httpReq = (HttpServletRequest) request;
        HttpServletResponse httpResp = (HttpServletResponse) response;

        if (!isWebSocketUpgrade(httpReq)) {
            chain.doFilter(request, response);
            return;
        }

        // Validate the request comes through our trusted reverse proxy
        if (!validateProxyChain(httpReq)) {
            httpResp.sendError(HttpServletResponse.SC_FORBIDDEN, "Direct access not allowed");
            return;
        }

        // Perform origin validation for WebSocket upgrade
        if (!validateOrigin(httpReq)) {
            httpResp.sendError(HttpServletResponse.SC_FORBIDDEN, "Origin not allowed");
            return;
        }

        // Validate CSRF token for WebSocket handshake
        if (!validateCsrfToken(httpReq)) {
            httpResp.sendError(HttpServletResponse.SC_FORBIDDEN, "Invalid CSRF token");
            return;
        }

        chain.doFilter(request, response);
    }

    private boolean isWebSocketUpgrade(HttpServletRequest req) {
        String upgrade = req.getHeader("Upgrade");
        return upgrade != null && upgrade.equalsIgnoreCase(WEBSOCKET_UPGRADE);
    }

    /**
     * Validates that the request arrived through our trusted nginx proxy.
     * The proxy injects a secret header that external clients cannot forge
     * because nginx strips any incoming X-Proxy-Secret header.
     */
    private boolean validateProxyChain(HttpServletRequest req) {
        String proxySecret = req.getHeader(PROXY_SECRET_HEADER);
        return TRUSTED_PROXY_SECRET.equals(proxySecret);
    }

    /**
     * Origin validation: checks the Origin header against allowed list.
     * When behind a reverse proxy, we also accept X-Forwarded-Origin
     * which the proxy sets from the original request's Origin header.
     */
    private boolean validateOrigin(HttpServletRequest req) {
        String origin = req.getHeader("Origin");
        String forwardedOrigin = req.getHeader("X-Forwarded-Origin");

        // Use forwarded origin if present (proxy scenario)
        String effectiveOrigin = forwardedOrigin != null ? forwardedOrigin : origin;

        if (effectiveOrigin == null || effectiveOrigin.isEmpty()) {
            // No origin header - could be same-origin or non-browser client
            // Allow if the request has valid session (authenticated)
            return hasValidSession(req);
        }

        return isOriginAllowed(effectiveOrigin);
    }

    /**
     * Checks if origin matches allowed list using prefix matching
     * to handle subdomains and port variations.
     */
    private boolean isOriginAllowed(String origin) {
        String normalizedOrigin = normalizeOrigin(origin);
        for (String allowed : ALLOWED_ORIGINS) {
            if (normalizedOrigin.startsWith(allowed)) {
                return true;
            }
        }
        return false;
    }

    private String normalizeOrigin(String origin) {
        return origin.toLowerCase(Locale.ROOT).trim();
    }

    /**
     * CSRF validation for WebSocket handshake.
     * Compares token from query parameter with session-stored token.
     */
    private boolean validateCsrfToken(HttpServletRequest req) {
        HttpSession session = req.getSession(false);
        if (session == null) {
            return false;
        }

        String sessionToken = (String) session.getAttribute("ws_csrf_token");
        String requestToken = req.getParameter("csrf_token");

        if (sessionToken == null || requestToken == null) {
            return false;
        }

        return timingSafeEquals(sessionToken, requestToken);
    }

    private boolean hasValidSession(HttpServletRequest req) {
        HttpSession session = req.getSession(false);
        return session != null && session.getAttribute("authenticated") != null;
    }

    /**
     * Constant-time string comparison to prevent timing attacks.
     */
    private boolean timingSafeEquals(String a, String b) {
        if (a.length() != b.length()) {
            return false;
        }
        int result = 0;
        for (int i = 0; i < a.length(); i++) {
            result |= a.charAt(i) ^ b.charAt(i);
        }
        return result == 0;
    }

    @Override
    public void destroy() {
    }
}
